fun pipelines() {
    val plates   = dishes.flatMapMerge(4) { d -> flow { emit(stove.cook(d)) } }   // default 16
    val inOrder  = dishes.flatMapConcat { d -> flow { emit(stove.cook(d)) } }  // outer paused in emit
    // no flatMapSequential: see the worked example
    val hits     = letters.flatMapLatest { q -> recipes.search(q) }             // waits for the old inner
    val byNumber = readings.zip(dial) { c, d -> Gap.of(c, d) }                  // the receiver has no shelf
    val latest   = combine(readings, dial) { c, d -> Gap.of(c, d) }             // may skip when slow
    val orders   = merge(tableOrders, takeawayOrders)
}

